const hosts = $json.result || [];
const hostids = hosts.map(h => h.hostid);
const now = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

// Chave de CPU: system.cpu.util (Zabbix Agent e Agent 2)
// Chave de Memoria: vm.memory.utilization (Agent 2) ou vm.memory.size[pused] (Agent classico)
return [{
  json: {
    hosts,
    generated_at: now,
    cpu_body: JSON.stringify({
      jsonrpc: '2.0', method: 'item.get', id: 2,
      params: {
        output: ['itemid', 'hostid', 'lastvalue', 'key_'],
        hostids: hostids,
        filter: { key_: 'system.cpu.util', status: 0 },
        monitored: true
      }
    }),
    mem_body: JSON.stringify({
      jsonrpc: '2.0', method: 'item.get', id: 3,
      params: {
        output: ['itemid', 'hostid', 'lastvalue', 'key_'],
        hostids: hostids,
        searchWildcardsEnabled: true,
        search: { key_: 'vm.memory.utilization' },
        monitored: true
      }
    })
  }
}];

const hosts      = $('Preparar Queries').item.json.hosts;
const cpuItems   = $('Zabbix API — Buscar CPU').item.json.result || [];
const memItems   = $json.result || [];
const now        = $('Preparar Queries').item.json.generated_at;

const CPU_THRESHOLD = 5;
const MEM_THRESHOLD = 20;

// Ultimo valor de CPU por host
const cpuByHost = {};
for (const item of cpuItems) {
  cpuByHost[item.hostid] = parseFloat(item.lastvalue);
}

// Ultimo valor de memoria por host
const memByHost = {};
for (const item of memItems) {
  memByHost[item.hostid] = parseFloat(item.lastvalue);
}

const report = [];
for (const host of hosts) {
  const cpu = cpuByHost[host.hostid] !== undefined ? Math.round(cpuByHost[host.hostid] * 10) / 10 : null;
  const mem = memByHost[host.hostid] !== undefined ? Math.round(memByHost[host.hostid] * 10) / 10 : null;
  const hasData = cpu !== null && mem !== null;
  const isGhost = hasData && cpu < CPU_THRESHOLD && mem < MEM_THRESHOLD;
  report.push({ host: host.name, hostname: host.host, cpu, mem, hasData, isGhost });
}

const ghosts = report.filter(r => r.isGhost);
const noData  = report.filter(r => !r.hasData);

return [{ json: { report, ghosts, noData, total: hosts.length, CPU_THRESHOLD, MEM_THRESHOLD, generated_at: now } }];

const { ghosts, noData, total, CPU_THRESHOLD, MEM_THRESHOLD, generated_at } = $json;

const color = ghosts.length === 0 ? '00B050' : (ghosts.length > 5 ? 'FF0000' : 'FFA500');

const sections = [{
  activityTitle: 'Relatorio de Hosts Fantasmas — ' + generated_at,
  activitySubtitle: ghosts.length + ' fantasma(s) de ' + total + ' hosts monitorados',
  facts: [
    { name: 'Criterio',             value: 'CPU < ' + CPU_THRESHOLD + '% E Memoria < ' + MEM_THRESHOLD + '%' },
    { name: 'Total monitorado',     value: String(total) },
    { name: 'Hosts fantasmas',      value: String(ghosts.length) },
    { name: 'Sem dados de metrica', value: String(noData.length) }
  ],
  markdown: true
}];

if (ghosts.length > 0) {
  sections.push({
    activityTitle: 'Hosts com Baixissimo Uso',
    text: ghosts.map(g => '**' + g.host + '** — CPU: ' + g.cpu + '% | Mem usada: ' + g.mem + '%').join('\n\n'),
    markdown: true
  });
}

if (noData.length > 0) {
  sections.push({
    activityTitle: 'Sem Dados (agente inativo ou item nao configurado)',
    text: noData.map(h => h.host).join(', '),
    markdown: true
  });
}

return [{
  json: {
    teams_body: JSON.stringify({
      '@type': 'MessageCard',
      '@context': 'http://schema.org/extensions',
      themeColor: color,
      summary: 'Hosts fantasmas: ' + ghosts.length + ' de ' + total,
      sections
    })
  }
}];
